// MigrationAgentServiceServer is the server API for MigrationAgentService service.
// All implementations must embed UnimplementedMigrationAgentServiceServer
// for forward compatibility.
//
// MigrationAgentService is implemented by the podmotion-agent DaemonSet on each node.
type MigrationAgentServiceServer interface {
	// PrepareSource validates the source pod is migratable and begins pre-copy if mode=PreCopy.
	PrepareSource(context.Context, *PrepareSourceRequest) (*PrepareSourceResponse, error)
	// PreDumpRound executes one iterative pre-dump round and returns dirty page stats.
	PreDumpRound(context.Context, *PreDumpRoundRequest) (*PreDumpRoundResponse, error)
	// Checkpoint performs the final freeze and CRIU dump.
	Checkpoint(context.Context, *CheckpointRequest) (*CheckpointResponse, error)
	// PrepareDestination pre-allocates pod netns, IP address, and storage on the destination node.
	PrepareDestination(context.Context, *PrepareDestinationRequest) (*PrepareDestinationResponse, error)
	// Restore performs CRIU restore on the destination node.
	Restore(context.Context, *RestoreRequest) (*RestoreResponse, error)
	// Verify confirms the restored pod is healthy and accepting traffic.
	Verify(context.Context, *VerifyRequest) (*VerifyResponse, error)
	// PrepareDestinationNetns pre-stages the migration network namespace on the destination
	// node and returns the file descriptor path and VTEP MAC for overlay FDB injection.
	PrepareDestinationNetns(context.Context, *PrepareDestinationNetnsRequest) (*PrepareDestinationNetnsResponse, error)
	// ConfirmOverlayReady evaluates the ADR-0049 atomicity barrier predicates B–F on the
	// destination node and returns the result. The controller calls this RPC after Restore
	// succeeds and before calling DisarmZeroWindow on the source node.
	// Predicate A (tcpi_unacked==0) is checked by ArmZeroWindow on the source node.
	ConfirmOverlayReady(context.Context, *ConfirmOverlayReadyRequest) (*ConfirmOverlayReadyResponse, error)
	// ArmZeroWindow attaches the zero_window eBPF program to the source pod veth TC egress,
	// causing the kernel to advertise win=0 on all outgoing ACKs, stalling the peer sender.
	// Must be called before FinalFreeze. The agent arms a watchdog that auto-disarms after
	// FreezeWindowBudgetMs + margin if DisarmZeroWindow is not received in time.
	ArmZeroWindow(context.Context, *ArmZeroWindowRequest) (*ArmZeroWindowResponse, error)
	// DisarmZeroWindow detaches the zero_window eBPF program from the source pod veth,
	// allowing the peer sender to resume. Must be called after CRIU restore is confirmed
	// complete and all 6 ADR-0049 barrier predicates are satisfied.
	DisarmZeroWindow(context.Context, *DisarmZeroWindowRequest) (*DisarmZeroWindowResponse, error)
	// Abort cancels an in-progress migration and triggers rollback.
	Abort(context.Context, *AbortRequest) (*AbortResponse, error)
	// EstimateCheckpoint performs a 10-second dirty page sampling without checkpointing.
	EstimateCheckpoint(context.Context, *EstimateCheckpointRequest) (*EstimateCheckpointResponse, error)
	// PutCheckpointTar receives a tar archive of checkpoint image files from the operator
	// and extracts them into the migration checkpoint directory on the destination node.
	// Used for same-cluster (LAN) cold migration where the operator can read source
	// checkpoint files directly and push them to the destination agent.
	PutCheckpointTar(context.Context, *PutCheckpointTarRequest) (*PutCheckpointTarResponse, error)
	// GetCheckpointTar reads the checkpoint image directory on the source agent and
	// returns a gzip-compressed tar of all files. This is a pure read — it does NOT
	// zeroize the source. The controller calls this, then PutCheckpointTar, then persists
	// CheckpointTransferred=true, then calls ReleaseCheckpoint to destroy the source copy.
	GetCheckpointTar(context.Context, *GetCheckpointTarRequest) (*GetCheckpointTarResponse, error)
	// ReleaseCheckpoint zeroizes and removes the checkpoint directory on this (source) node.
	// Called by the controller only after PutCheckpointTar has succeeded AND
	// pm.Status.CheckpointTransferred has been durably persisted. Idempotent: returns
	// success if the directory is already absent (handles controller-restart replay).
	ReleaseCheckpoint(context.Context, *ReleaseCheckpointRequest) (*ReleaseCheckpointResponse, error)
	// KillFrozenSource delivers SIGKILL directly to the source process left in SIGSTOP by
	// a LeaveStopped=true CRIU dump (see registerFrozenSource), via the same unconfined
	// netns-broker path thawFrozenSource uses for SIGCONT. Unlike a Kubernetes pod delete
	// (which always resumes a stopped container's init process — SIGCONT-then-signal — to
	// run its stop sequence, giving app-level shutdown code a window to run and mutate
	// on-disk state before the final SIGKILL lands), this terminates the STILL-STOPPED
	// process straight from the kernel: SIGKILL is fatal to a stopped task without ever
	// resuming it to userspace, so no application shutdown/cleanup code ever executes.
	// Used by the ADR-0356 Tier1-Longhorn early source release, where the source and
	// destination share the same underlying volume and any app-level shutdown hook that
	// touches shared on-disk state (e.g. a database unlinking its own lock file) would
	// corrupt state out from under the already-restored destination process. Idempotent:
	// returns success if no frozen-source record exists for migration_name (e.g. it was
	// already thawed or killed).
	KillFrozenSource(context.Context, *KillFrozenSourceRequest) (*KillFrozenSourceResponse, error)
	// InjectIPHandoff installs neighbor/FDB entries on the DESTINATION node so the OLD
	// pod IP becomes reachable at the replacement pod's veth MAC (ADR-0133 Decision 2).
	// Called by the controller in reconcileVerifying after criuRestoreConfirmed=true and
	// before DisarmZeroWindow. Idempotent (RTM_NEWNEIGH NLM_F_REPLACE). The response
	// returns the destination node's VTEP MAC and an in-node reachability probe result.
	InjectIPHandoff(context.Context, *InjectIPHandoffRequest) (*InjectIPHandoffResponse, error)
	// CleanupSourceIPHandoff removes the stale ARP/neighbor and FDB entries for the OLD
	// pod IP on the SOURCE node after traffic has moved to the replacement (ADR-0133
	// Decision 4). Deferred until after TrafficVerified=True and DisarmZeroWindow.
	// Idempotent: ENOENT is treated as success.
	CleanupSourceIPHandoff(context.Context, *CleanupSourceIPHandoffRequest) (*CleanupSourceIPHandoffResponse, error)
	// InjectSourceRedirect installs the SOURCE-node VXLAN redirect for the OLD pod IP
	// (ADR-0136). Because the OLD IP is in the source node's own pod CIDR, the kernel
	// otherwise routes it to the dead local cni0 bridge. This installs three consistent
	// entries on flannel.1 — a /32 route, an AF_INET neigh (oldIP->replVethMAC) and an
	// AF_BRIDGE FDB (replVethMAC->destNodeIP) — so traffic is VXLAN-encapsulated to the
	// destination VTEP instead. Called from injectIPHandoff after the destination probe
	// passes; torn down by CleanupSourceIPHandoff after TrafficVerified=True. Idempotent.
	InjectSourceRedirect(context.Context, *InjectSourceRedirectRequest) (*InjectSourceRedirectResponse, error)
	// DisarmTCRedirect removes the ADR-0139 tc-ingress redirect (filter + ingress qdisc) from
	// the destination overlay interface (flannel.1) after TrafficVerified=True (Decision 3
	// disarm order). Idempotent: ENOENT is treated as success.
	DisarmTCRedirect(context.Context, *DisarmTCRedirectRequest) (*DisarmTCRedirectResponse, error)
	// VerifyTCP reads /proc/<pid>/net/tcp[6] on the destination node post-restore and
	// compares each ESTABLISHED 4-tuple's snd_nxt/rcv_nxt against the source SeqSnapshots
	// captured at freeze. Returns verified=true only when all connections match within
	// ±MSS (1448 bytes). Also issues the ApplicationProbe (SQL/TCP) when configured.
	// Called by the controller during TCPVerifying phase per ADR-0019 Amendment A.
	VerifyTCP(context.Context, *VerifyTCPRequest) (*VerifyTCPResponse, error)
	// ProbeDataplaneReachability is called by the CONTROLLER on the SOURCE-NODE agent
	// (a node != destination) to dial the preserved pod IP cross-node and confirm the
	// real overlay/host-route datapath is live. ADR-0210: this replaces the ADR-0200/0201
	// in-netns self-probe tautology. The dial originates from the source node's HOST netns
	// (NOT a pod netns) so its SYN traverses the real overlay (VXLAN/VTEP), not a local
	// lo/32 alias. The destination must echo back the controller-issued correlation nonce
	// (round-tripped through the dialed listener) — the source agent cannot synthesize
	// success alone. The controller is the authority that flips DataplaneReachabilityVerified.
	ProbeDataplaneReachability(context.Context, *ProbeDataplaneReachabilityRequest) (*ProbeDataplaneReachabilityResponse, error)
	// StartReachabilityEcho is called by the controller on the DESTINATION-node agent to
	// open a short-lived TCP listener INSIDE the replacement pod netns, bound to the
	// preserved pod IP, that echoes back the controller-issued nonce to any connecting
	// client and then closes. This is the destination half of the ADR-0210 nonce round-trip:
	// it proves a SYN that reached the preserved IP traversed the real cross-node datapath
	// (the listener owns the IP only inside the replacement pod netns on THIS node).
	StartReachabilityEcho(context.Context, *StartReachabilityEchoRequest) (*StartReachabilityEchoResponse, error)
	// VerifyCleanup probes whether the datapath objects for a given cleanup scope are still
	// present on the calling node (ADR-0241 / NR-BLOCK-1). CUTOVER_COMPLETE scope (the only
	// scope implemented today) checks the cni0 neigh + cni0 host route removed by
	// CleanupSourceIPHandoff. IP_RECLAIM scope is defined for forward-compatibility with
	// NR-BLOCK-2 (the dest tc/FORWARD-ACCEPT/NOTRACK + source flannel.1/NOTRACK objects) but
	// returns Unimplemented until that follow-on ADR lands — there is no cleanup path to
	// verify the absence of yet. The explicit objects list lets a future ADR change what is
	// checked without a new RPC signature (ADR-0241 Decision 1).
	VerifyCleanup(context.Context, *VerifyCleanupRequest) (*VerifyCleanupResponse, error)
	// TeardownSourceRedirect removes the ADR-0136 SOURCE-node flannel.1 VXLAN redirect
	// (host route + AF_INET neigh + AF_BRIDGE FDB) and the ADR-0141 source-mode NOTRACK
	// rules for the relocated OLD pod IP. Symmetric to DisarmTCRedirect on the destination
	// side. Called only once the controller's IP-Reclaim-Eligible predicate holds
	// (ADR-0244 / NR-BLOCK-2). Idempotent: ENOENT is treated as success.
	TeardownSourceRedirect(context.Context, *TeardownSourceRedirectRequest) (*TeardownSourceRedirectResponse, error)
	// ProbeConntrackForIP reports whether the calling node's conntrack table has any entry
	// matching old_pod_ip (source or destination address), via network.ExportConntrack — a
	// read-only presence probe, not an export-for-migration call. Used by the controller's
	// NoLiveConntrackForIP conjunct (ADR-0244 R6 / NR-BLOCK-2): a non-empty result on EITHER
	// the source or destination agent defers the entire IP-reclaim sweep pass.
	ProbeConntrackForIP(context.Context, *ProbeConntrackForIPRequest) (*ProbeConntrackForIPResponse, error)
	// ProbeDestSocketForIP reports whether the DESTINATION agent's restored-pod network
	// namespace has an ESTABLISHED TCP socket bound to old_pod_ip, read directly from
	// /proc/<restoredPID>/net/tcp[6] inside that netns. This observes the class of flow
	// ADR-0141's NOTRACK rules deliberately make invisible to ProbeConntrackForIP/conntrack
	// (ADR-0244 C1 correction, Sprint 40): a live pinned/source-CIDR connection carried over
	// the NOTRACK'd tc-redirect path never appears in conntrack by construction, so it must
	// be observed at the socket-table layer instead. Called only against the destination
	// agent (the restored pod owns old_pod_ip post-migration); the source node has no
	// socket bound to old_pod_ip to inspect.
	ProbeDestSocketForIP(context.Context, *ProbeDestSocketForIPRequest) (*ProbeDestSocketForIPResponse, error)
	mustEmbedUnimplementedMigrationAgentServiceServer()
}

